'use strict';
const el=id=>document.getElementById(id),bridge='http://127.0.0.1:8792';let proposals=[],week=0,treatment=0,token=null,ready=false;
const dates=['2026-10-07','2026-10-14','2026-10-21','2026-10-28'];const message=s=>el('web-status').textContent=s;
function current(){return proposals.filter(p=>p.week===dates[week])[treatment];}
function reset(){el('web-confirm').checked=false;el('web-schedule').disabled=true;el('web-receipt').hidden=true;message('');}
function draw(){reset();const a=current();document.querySelectorAll('#web-weeks button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===week)));document.querySelectorAll('#treatments button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===treatment)));el('web-title').textContent=a.props.title;el('web-context').textContent='One small website treatment, coordinated with the '+Number(a.week.slice(-2))+' October email and its social tiles.';el('proposal-name').textContent=a.name;el('proposal-why').textContent=a.rationale;el('proposal-where').textContent=a.placement;el('proposal-window').textContent=Number(a.week.slice(-2))+' October, 8am to '+new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'long',timeZone:'Australia/Melbourne'}).format(new Date(a.props.end))+', 8am (Melbourne time)';el('web-checks').replaceChildren(...a.required_checks.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));el('website-frame').src='website/'+a.id+'.html';el('web-confirm').disabled=!ready;history.replaceState(null,'','#'+a.id);}
async function api(path,body){const r=await fetch(bridge+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},...(body?{body:JSON.stringify(body)}:{})});const j=await r.json();if(!r.ok)throw Error(j.error||'The website update could not be confirmed.');return j;}
async function connect(){try{await api('/api/website/status');ready=true;el('web-connection').textContent='Connected. Approval will queue the exact weekly update for Remy.';el('web-connect').textContent='Approval desk connected';el('web-confirm').disabled=false;}catch(e){ready=false;token=null;el('web-confirm').disabled=true;message(e instanceof TypeError?'Start the PI Email Desk launcher and allow local access, or open this review in the local desk.':e.message);}}
el('web-connect').addEventListener('click',()=>{const w=window.open(bridge+'/connect?origin='+encodeURIComponent(location.origin),'pi-website-connect','width=520,height=480');if(!w)message('Allow the connection window, then reconnect.');});
window.addEventListener('message',e=>{if(e.origin!==bridge||e.data?.type!=='pi-beehiiv-connected'||typeof e.data.token!=='string')return;token=e.data.token;connect();});
el('web-confirm').addEventListener('change',()=>el('web-schedule').disabled=!el('web-confirm').checked||!ready);
el('web-schedule').addEventListener('click',async()=>{const a=current();el('web-schedule').disabled=true;el('web-confirm').disabled=true;message('Recording approval and confirming the job in Remy’s scheduler…');try{const receipt=await api('/api/website/schedule',{id:a.id,sha256:a.sha256,confirmed:el('web-confirm').checked});message((receipt.reused?'This update was already scheduled. ':'Update job scheduled for Remy. ')+'Job '+receipt.job_id+'. Website execution is pending.');const blob=new Blob([JSON.stringify(receipt,null,2)],{type:'application/json'});el('web-receipt').href=URL.createObjectURL(blob);el('web-receipt').download=a.id+'-approval-receipt.json';el('web-receipt').hidden=false;}catch(e){message(e.message+' No website update is being claimed.');el('web-confirm').disabled=!ready;el('web-schedule').disabled=!ready;}});
(async()=>{try{proposals=(await fetch('website-proposals.json').then(r=>r.json())).proposals;el('web-weeks').replaceChildren(...dates.map((d,i)=>{const b=document.createElement('button');b.type='button';b.className='week';b.textContent=Number(d.slice(-2))+' October';b.onclick=()=>{week=i;draw();};return b;}));el('treatments').replaceChildren(...['Homepage feature','Weekly badge','Click-to-open invitation'].map((t,i)=>{const b=document.createElement('button');b.type='button';b.textContent=t;b.onclick=()=>{treatment=i;draw();};return b;}));const selected=proposals.find(p=>p.id===location.hash.slice(1));if(selected){week=dates.indexOf(selected.week);treatment=['band','badge','slide'].indexOf(selected.props.variant);}draw();if(location.origin===bridge){token=(await fetch(bridge+'/api/session').then(r=>r.json())).token;connect();}}catch(e){message('The proposals could not load. Reload this page.');}})();
